  patterns: [
    [/^(\d+) files are ready$/, "$1 archivos listos"],
    [/^(.+) · done in ([\d.]+) s, on your computer$/, "$1 · hecho en $2 s, en tu ordenador"],
    [/^(\d+) file\(s\) · (\d+) page\(s\) · (.+)$/, "$1 archivo(s) · $2 página(s) · $3"],
    [/^(\d+) image\(s\) · (.+)$/, "$1 imagen(es) · $2"],
    [/^Saved (\d+) file\(s\) into “(.*)”\.$/, "Se guardaron $1 archivo(s) en «$2»."],
    [/^(\d+) of (\d+)$/, "$1 de $2"],
    [/^Page (\d+)$/, "Página $1"],
    [/^Downloading the AI model, first time only: (\d+) of (\d+) MB$/, "Descargando el modelo de IA, solo la primera vez: $1 de $2 MB"],
    [/^Finding the subject: (.*)$/, "Buscando el sujeto: $1"],
    [/^Background removed from (\d+) photos$/, "Fondo eliminado de $1 fotos"],
    [/^(\d+) photo\(s\)$/, "$1 foto(s)"],
    [/^(\d+) image\(s\)$/, "$1 imagen(es)"],
    [/^(\d+) image\(s\) → (.+)$/, "$1 imagen(es) → $2"],
    [/^(\d+) page\(s\) in the new PDF$/, "$1 página(s) en el nuevo PDF"],
    [/^Your PDFs? (?:is|are) (\d+)% smaller$/, "Tus PDF pesan un $1 % menos"],
    [/^(\d+) files → 1 PDF of (\d+) pages$/, "$1 archivos → 1 PDF de $2 páginas"],
    [/^Page (\d+): (.*)$/, "Página $1: $2"],
    [/^Comparing page (\d+) of (\d+)…$/, "Comparando la página $1 de $2…"],
    [/^(\d+) of (\d+) page\(s\) changed$/, "$1 de $2 página(s) cambiaron"],
    [/^Converting: (.*)$/, "Convirtiendo: $1"],
    [/^(\d+) files? · (\d+) pages?$/, "$1 archivo(s) · $2 página(s)"],
    [/^(\d+) pages?$/, "$1 página(s)"],
    [/^(\d+) files?$/, "$1 archivo(s)"],
  ],
